def pancake_sort(nums):
    arr_len = len(nums)
    while arr_len > 1:
        mi = nums.index(max(nums[:arr_len]))
        if mi != 0:
            nums[:mi+1] = nums[:mi+1][::-1]
        nums[:arr_len] = nums[:arr_len][::-1]
        arr_len -= 1
    return nums

